// Generated by pnpm worker:build-context -- always runs before tsup in worker:build

import { createGeminiChat } from "@tanstack/ai-gemini";
import { createChatHandler } from "./chat-handler.js";
import { getCorsHeaders } from "./cors.js";
import { CHUNKS, SEARCH_INDEX_JSON, VOCABULARY } from "./docs-context.js";
import { handleLegacyRequest } from "./legacy-handler.js";
import { nowMs } from "./rate-limit.js";

type Env = Record<string, string>;
type RouteHandler = (
  request: Request,
  env: Env,
  cors: Record<string, string>,
) => Promise<Response>;

export interface Routes {
  /** `POST /` — the frozen protocol the live site's current client speaks (D3). */
  legacy: RouteHandler;
  /** `POST /api/chat` — the new protocol. */
  chat: RouteHandler;
}

function errorResponse(
  status: number,
  error: string,
  cors: Record<string, string>,
): Response {
  return new Response(JSON.stringify({ error, retryable: false }), {
    status,
    headers: { "Content-Type": "application/json", ...cors },
  });
}

export function createWorker(routes: Routes) {
  return {
    async fetch(request: Request, env: Env): Promise<Response> {
      const cors = getCorsHeaders(request.headers.get("origin"));

      if (request.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: cors });
      }

      const { pathname } = new URL(request.url);
      const route =
        pathname === "/"
          ? routes.legacy
          : pathname === "/api/chat"
            ? routes.chat
            : null;
      if (route === null) return errorResponse(404, "Not found.", cors);
      if (request.method !== "POST") {
        return errorResponse(405, "Method not allowed.", {
          ...cors,
          Allow: "POST, OPTIONS",
        });
      }
      return route(request, env, cors);
    },
  };
}

export default createWorker({
  legacy: handleLegacyRequest,
  chat: createChatHandler({
    createAdapter: createGeminiChat,
    corpus: {
      chunks: CHUNKS,
      searchIndexJson: SEARCH_INDEX_JSON,
      vocabulary: VOCABULARY,
    },
    now: nowMs,
  }),
});
